from pathlib import Path
import json,csv,re,sys,hashlib
R=Path(__file__).resolve().parents[2];O=R/'docs/ultimate-release-2026-10-19';sys.path.insert(0,str(R/'tools'))
from normalize_calculator_layouts import Document
from build_ultimate_release import pages,markets,articles

def save(name,rows):
 with (O/name).open('w',encoding='utf-8',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def shotname(route):return 'home-us' if route=='/' else route[1:].replace('/','-').replace('.html','').rstrip('-')
browser=json.loads((O/'after/browser-results.json').read_text(encoding='utf-8'));rendered={r['route']:r for r in browser['renders']};rows=[];motion=[]
new={r['slug'].removesuffix('.html')+'.html' for r in articles()}
for p in pages():
 rel=p.relative_to(R).as_posix();route='/' if rel=='index.html' else '/'+rel.removesuffix('index.html') if rel.endswith('/index.html') else '/'+rel
 s=p.read_text(encoding='utf-8');d=Document(s);main=next(n for n in d.nodes if n['tag']=='main');family=main['attrs'].get('data-family') or ('homepage' if 'data-home-template' in main['attrs'] else 'reading/tool')
 shots=[x for x in browser['screens'] if x.startswith(shotname(route)+'-')]
 rows.append({'route':route,'template':family,'market':re.search(r'data-market-scope="([^"]*)"',s)[1],'implementation':'Four shared themes, native navigation, focus and motion; purposeful family styles. New editorial template.' if rel in new else 'Shared palette, controls and motion; original content/data retained. Core workspaces separately refined.','source_status':'Source-checked authored guide; source trail in publication manifest.' if rel in new else 'Existing source/provenance retained; no new menu values claimed.','SEO':'Self-canonical and metadata validated; private states excluded. Indexing unverified.','functional_evidence':'after/browser-results.json; tests.json','responsive_checks':'320,390,768,1024,1440 for representative families; all routes at1280','route_browser_render':str(route in rendered),'screenshot':'; '.join('after/'+x for x in shots),'visual_review':'Representative family / article screenshots reviewed; no claim of individual visual approval for every record.' if shots else 'Shared family reviewed; route rendered programmatically.','remaining':'Exact meal photography rights/coverage incomplete. GA4/Journey audience data unavailable.'})
 motion.append({'route':route,'family':family,'global':'Button feedback, navigation glide, native panel opening, preference selection; reduced/calm behavior.','family_interaction':'Quiz selection/steps and stable results' if 'finder' in route or 'find-a-meal' in route else 'Calculator stages and result reveal' if 'calculator' in family or 'calculators' in route else 'Entry settling, tab indicator and logging feedback' if 'diary' in route else 'Game selection and completion feedback' if '/play' in route else 'Illustration hover and clear table scroll state; reading area stays still' if rel in new or 'articles' in route else 'Contextual selections/cards/tables; reading area remains still.','evidence':'after/product-interactions.zip; after/browser-results.json','verification_limit':'Shared module integration checked on every route; traces sample interactions, not every element.'})
save('release-inventory.csv',rows);save('motion-coverage.csv',motion)
